export const MONUMENTS = JSON.parse("[{\"id\":\"n5895117611\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Я. Домбровскому\",\"x\":-3284.7,\"z\":-134.8,\"subject\":\"Q465213\",\"inscription\":\"В этом здании бывшей Академии Генерального штаба в 1859—1861 годах учился польский революционер-демократ Ярослав Домбровский, генерал, главнокомандующий вооруженными силами Парижской коммуны. Погиб в 1871 году в бою с версальцами\"},{\"id\":\"n6423969736\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3106.7,\"z\":-138.6,\"inscription\":\"В этом здании с 4 по 14 сентября 1941 года формировалась 6-я дивизия Народного ополчения, участвовавшая в обороне Ленинграда\"},{\"id\":\"n3637244104\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"x\":-4375.3,\"z\":-192.1,\"inscription\":\"1941-1945\"},{\"id\":\"n8839661365\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. С. Завойко\",\"x\":-4572.3,\"z\":-147.8,\"subject\":\"Q163876\",\"inscription\":\"Адмирал Василий Степанович Завойко 1810-1898, почётный гражданин г. Петропавловска-Камчатского. В этом доме в 1856 г. проживал первый военный губернатор Камчатской области, руководитель петропавловской обороны от англо-французской эскадры в августе 1854 г\"},{\"id\":\"n7727097105\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ю. А. Билибину\",\"x\":-4703.1,\"z\":-189.2,\"subject\":\"Q724267\",\"inscription\":\"В этом доме с 1925 по 1949 год жил выдающийся советский геолог, лауреат государственной премии, член-корреспондент Академии Наук СССР Юрий Александрович Билибин\"},{\"id\":\"n5611461009\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Н. К. Рериху\",\"x\":-5249.1,\"z\":-181.5,\"subject\":\"Q208993\"},{\"id\":\"n8875709792\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. Д. Шаргородскому\",\"x\":-4976,\"z\":-185.9,\"subject\":\"Q4520483\",\"inscription\":\"Михаил Давидович Шаргородский, Профессор, выдающийся учёный криминолог, доктор юридических наук работал на юридическом факультете Санкт-Петербургского (Ленинградского) государственного университета с 1954 года по 1973 год\"},{\"id\":\"n8875711576\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4970.3,\"z\":-176,\"inscription\":\"Граждане! При артобстреле эта сторона улицы наиболее опасна. В память о героизме и мужестве ленинградцев в дни 900 дневной блокады города сохранена эта надпись.\"},{\"id\":\"n8875712184\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. В. Венедиктову\",\"x\":-4974.1,\"z\":-182.6,\"subject\":\"Q4107122\",\"inscription\":\"Анатолий Васильевич Венедиктов, Академик, выдающийся учёный-юрист, Декан юридического факультета (1944-1949 г.г.) работал на юридическом факультете Санкт-Петербургского (Ленинградского) государственного университета с 1944 года по 1959 год\"},{\"id\":\"n13175156970\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"В. Д. Спасовичу\",\"x\":-4940.9,\"z\":-129.6,\"material\":\"bronze\",\"startDate\":\"22.11.2024\",\"subject\":\"Владимир Данилович Спасович\",\"artist\":\"Алексей Степаненко\",\"description\":\"Памятник русскому юристу, адвокату и профессору\"},{\"id\":\"n3714795725\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"Подвигу пожарных Ленинграда\",\"x\":-4882.2,\"z\":-164.7}]");
